class Trajectory:
    nodes: tuple[Symbol, ...]
    hops: tuple[Hop, ...] = ()

    @property
    def current_node(self) -> Symbol:
        return self.nodes[-1]

    @property
    def depth(self) -> int:
        return len(self.hops)

    @property
    def node_ids(self) -> tuple[str, ...]:
        return tuple(node.id for node in self.nodes)

    def creates_cycle(self, symbol: Symbol) -> bool:
        return symbol.id in self.node_ids

    def extend(
        self,
        relation: Relation,
        target: Symbol,
        objectives: ObjectiveVector,
        entropy: float,
        novelty: float,
        contract: ContractScore,
        reason: str,
    ) -> Trajectory:
        hop = Hop(
            source=self.current_node,
            relation=relation,
            target=target,
            hop_number=self.depth + 1,
            objective_vector=objectives,
            entropy=entropy,
            novelty=novelty,
            contract=contract,
            reason=reason,
        )
        return Trajectory(nodes=(*self.nodes, target), hops=(*self.hops, hop))

