def test_non_dominated_sort_multiple_fronts_with_negative_hop() -> None:
    best = _state("best", ObjectiveVector(0.9, -0.1, 1.0, 1.0))
    middle = _state("middle", ObjectiveVector(0.8, -0.2, 0.8, 0.8))
